def copiar_endereco_antigo(apps, schema_editor):
    """Cadastros antigos só têm o endereço em texto livre: copia esse texto
    para o logradouro, para não aparecer vazio na tela de edição (o usuário
    completa número, bairro, cidade e UF ao editar)"""
    Farmacia = apps.get_model('farmacia', 'Farmacia')
    for farmacia in Farmacia.objects.filter(logradouro=''):
        farmacia.logradouro = farmacia.endereco[:150]
        farmacia.save(update_fields=['logradouro'])


